import { MakeLogicType, afterMount, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { productSetupStatusLogic } from 'lib/components/ProductEmptyState/productSetupStatusLogic'
import type { ProductSetupStatus } from 'lib/components/ProductEmptyState/types'

import { ProductKey } from '~/queries/schema/schema-general'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linksSetupLogicValues {
    setupStatus: ProductSetupStatus // productSetupStatusLogic
    linkCount: number | null
    linkCountLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linksSetupLogicActions {
    setDetectedStatus: (status: ProductSetupStatus) => {
        status: ProductSetupStatus
    } // productSetupStatusLogic
    loadLinkCount: (_: void) => void
    loadLinkCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadLinkCountSuccess: (
        linkCount: number,
        payload?: void
    ) => {
        linkCount: number
        payload?: void
    }
}

export type linksSetupLogicType = MakeLogicType<linksSetupLogicValues, linksSetupLogicActions>

/**
 * Setup detection for the links empty state. Links are a creation-first product,
 * so "set up" simply means the project has at least one link - no event or traffic
 * signal involved. Re-checks on every mount (the scene gate mounts it), which
 * covers returning from the link creation page.
 */
export const linksSetupLogic = kea<linksSetupLogicType>([
    path(['products', 'links', 'frontend', 'emptyState', 'linksSetupLogic']),
    connect(() => ({
        actions: [productSetupStatusLogic({ productKey: ProductKey.LINKS }), ['setDetectedStatus']],
        values: [productSetupStatusLogic({ productKey: ProductKey.LINKS }), ['status as setupStatus']],
    })),
    loaders({
        linkCount: [
            null as number | null,
            {
                loadLinkCount: async (_: void, breakpoint): Promise<number> => {
                    const response = await api.links.list({ limit: 1 })
                    breakpoint()
                    return response.count
                },
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        loadLinkCountSuccess: ({ linkCount }) => {
            actions.setDetectedStatus(linkCount !== null && linkCount > 0 ? 'has-data' : 'needs-setup')
        },
        loadLinkCountFailure: () => {
            // Never strand the gate on its spinner: if nothing has answered yet, fail
            // open to the real scene. Don't downgrade an existing answer on a blip.
            if (values.setupStatus === 'loading') {
                actions.setDetectedStatus('unknown')
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadLinkCount()
    }),
])
